// --- algo_lib.InTextFile.temp_buf.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
u8& algo_lib::temp_buf_Alloc(algo_lib::InTextFile& parent) {
    u8* row = temp_buf_AllocMaybe(parent);
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("algo_lib.out_of_mem  field:algo_lib.InTextFile.temp_buf  comment:'Alloc failed'");
    }
    return *row;
}

// --- algo_lib.InTextFile.temp_buf.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
u8* algo_lib::temp_buf_AllocMaybe(algo_lib::InTextFile& parent) {
    u8 *row = (u8*)temp_buf_AllocMem(parent);
    if (row) {
        new (row) u8; // call constructor
    }
    return row;
}

// --- algo_lib.InTextFile.temp_buf.RemoveAll
// Destroy all elements of Inlary
void algo_lib::temp_buf_RemoveAll(algo_lib::InTextFile& parent) {
    parent.temp_buf_n = 0;
}

// --- algo_lib.InTextFile.temp_buf.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void algo_lib::temp_buf_RemoveLast(algo_lib::InTextFile& parent) {
    u64 n = parent.temp_buf_n;
    if (n > 0) {
        n -= 1;
        parent.temp_buf_n = n;
    }
}

// --- algo_lib.InTextFile.temp_buf.Print
// Convert temp_buf to a string.
// Array is printed as a regular string.
void algo_lib::temp_buf_Print(algo_lib::InTextFile& parent, algo::cstring &rhs) {
    rhs << algo::memptr_ToStrptr(temp_buf_Getary(parent));
}

// --- algo_lib.InTextFile.temp_buf.ReadStrptrMaybe
// Read array from string
// Convert string to field. Return success value
bool algo_lib::temp_buf_ReadStrptrMaybe(algo_lib::InTextFile& parent, algo::strptr in_str) {
    bool retval = true;
    i32 newlen = i32_Min(in_str.n_elems, 8192);
    memcpy(reinterpret_cast<u8*>(parent.temp_buf_data), in_str.elems, newlen);
    parent.temp_buf_n = newlen;
    return retval;
}

// --- algo_lib.InTextFile..Init
// Set all fields to initial values.
void algo_lib::InTextFile_Init(algo_lib::InTextFile& parent) {
    parent.own_fd = bool(true);
    parent.temp_buf_n = 0; // temp_buf: initialize count
}

// --- algo_lib.InTextFile..Uninit
void algo_lib::InTextFile_Uninit(algo_lib::InTextFile& parent) {
    file_Cleanup(parent); // dmmeta.ffunc:algo_lib.InTextFile.file/Cleanup

    // algo_lib.InTextFile.temp_buf.Uninit (Inlary)  //
    temp_buf_RemoveAll(parent);
}

// --- algo_lib.RecSortkey..Cmp
i32 algo_lib::RecSortkey_Cmp(algo_lib::RecSortkey& lhs, algo_lib::RecSortkey& rhs) {
    i32 retval = 0;
    retval = algo::Smallstr150_Cmp(lhs.ctype, rhs.ctype);
    if (retval != 0) {
        return retval;
    }
    retval = double_Cmp(lhs.num, rhs.num);
    if (retval != 0) {
        return retval;
    }
    retval = algo::cstring_Cmp(lhs.str, rhs.str);
    if (retval != 0) {
        return retval;
    }
    retval = float_Cmp(lhs.rowid, rhs.rowid);
    return retval;
}

// --- algo_lib.RecSortkey..Eq
bool algo_lib::RecSortkey_Eq(algo_lib::RecSortkey& lhs, algo_lib::RecSortkey& rhs) {
    bool retval = true;
    retval = algo::Smallstr150_Eq(lhs.ctype, rhs.ctype);
    if (!retval) {
        return false;
    }
    retval = double_Eq(lhs.num, rhs.num);
    if (!retval) {
        return false;
    }
    retval = algo::cstring_Eq(lhs.str, rhs.str);
    if (!retval) {
        return false;
    }
    retval = float_Eq(lhs.rowid, rhs.rowid);
    return retval;
}

// --- algo_lib.RecSortkey..Print
// print string representation of ROW to string STR
// cfmt:algo_lib.RecSortkey.String  printfmt:Tuple
void algo_lib::RecSortkey_Print(algo_lib::RecSortkey& row, algo::cstring& str) {
    algo::tempstr temp;
    str << "algo_lib.RecSortkey";

    algo::Smallstr150_Print(row.ctype, temp);
    PrintAttrSpaceReset(str,"ctype", temp);

    double_Print(row.num, temp);
    PrintAttrSpaceReset(str,"num", temp);

    algo::cstring_Print(row.str, temp);
    PrintAttrSpaceReset(str,"str", temp);

    float_Print(row.rowid, temp);
    PrintAttrSpaceReset(str,"rowid", temp);
}

